import{z as n,x as o,o as e,c as P,q as l,j as s,D as A,d as r,s as i,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"WPA2 / WPA3","description":"","frontmatter":{"title":"WPA2 / WPA3","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wpa2-wpa3.md","filePath":"cs/wpa2-wpa3.md","lastUpdated":1791063341000}'),p={name:"cs/wpa2-wpa3.md"};function d(S,a,h,W,m,T){const t=o("Mermaid");return e(),P("div",null,[a[2]||(a[2]=l('<h1 id="wpa2-wpa3" tabindex="-1">WPA2 / WPA3 <a class="header-anchor" href="#wpa2-wpa3" aria-label="Permalink to &quot;WPA2 / WPA3&quot;">​</a></h1><div class="epigraph"><p>无线是广播介质：加密与认证必须当所有邻居都在听。WPA2-PSK 把口令变成全网共享秘密；WPA3-SAE 改善握手，口令仍不是企业身份。</p><footer>—— IEEE 802.11i；WPA3 规范；对照 Fluhrer 对 WEP 的历史教训</footer></div><p>上一课<a href="/cs/vpn-zero-trust">VPN 与零信任</a>警告位置不等于身份。缺口是<strong>最后一跳</strong>：802.11。WEP 已死；本课对照 WPA2 与 WPA3，不把射频当光刻课。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放网络无保密。WPA2-PSK：同一口令派生 PTK，握手可被离线猜口令——只陈述性质。企业 802.1X 把身份交给 RADIUS。WPA3-SAE 抗离线猜（在合同内）。缺口是链路层合同，不是应用 SSO。</p><p><span class="marginnote">术语翻译：PTK（成对临时密钥）就是这一次连接专用的会话密钥，由口令/PMK 与双方随机数派生，断开即弃。四次握手的作用正是让两端在不暴露口令的前提下，确认彼此算出了同一把 PTK。</span></p><h3 id="访客与分割" tabindex="-1">访客与分割 <a class="header-anchor" href="#访客与分割" aria-label="Permalink to &quot;访客与分割&quot;">​</a></h3><p>同一 SSID 上的客户隔离是策略。PSK 网里邻居曾能彼此解密广播的历史问题，要用隔离与企业认证。</p><p><span class="marginnote">802.11i。KRACK 作为重装密钥的失败模式点名，不给步骤。Dragonfly/SAE 是 WPA3 个人模式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分个人 PSK 与企业 EAP。指出管理帧保护、前向保密在 WPA3 的改进。对照：上了 WPA3 仍要 vis-à-vis 应用 TLS——链路密钥不管 HTTPS 以外的威胁全覆盖。</p><p><span class="marginnote">常见误区：以为换了 WPA3，网站密码与聊天内容就全安全了。链路加密只覆盖「手机到路由器」这一跳；出路由器走互联网的流量仍靠 HTTPS/TLS 自己的密钥。两段各管一半，不能互相顶替。</span></p>',13)),(e(),s(B,null,{default:A(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PSK%5B%22%E5%85%B1%E4%BA%AB%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20WPA2%5B%22WPA2%20%E5%9B%9B%E6%AC%A1%E6%8F%A1%E6%89%8B%22%5D%0A%20%20SAE%5B%22SAE%22%5D%20--%3E%20WPA3%5B%22WPA3%20%E4%B8%AA%E4%BA%BA%22%5D%0A%20%20EAP%5B%22802.1X%22%5D%20--%3E%20ENT%5B%22%E4%BC%81%E4%B8%9A%E8%BA%AB%E4%BB%BD%22%5D%0A%20%20ENT%20--%3E%20PMK%5B%22%E6%AF%8F%E7%94%A8%E6%88%B7%20PMK%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"广播介质迫使 AEAD 与认证在链路上出现。PSK 把口令熵当成全网密钥材料。下一课离开链路，看名称系统：DNS 缓存如何把人带到错误的 TLS 名前。",-1)),a[5]||(a[5]=E("p",null,"WPA3 抗离线猜到底强在哪：",-1)),(e(),s(B,null,{default:A(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E6%8A%93%E5%88%B0%E4%B8%80%E6%AC%A1%20WPA2%20%E6%8F%A1%E6%89%8B%22%5D%20--%3E%20OFF%5B%22%E7%A6%BB%E7%BA%BF%E7%A9%B7%E4%B8%BE%E5%8F%A3%E4%BB%A4%EF%BC%8C%E9%9A%8F%E4%BE%BF%E8%AF%95%E7%99%BE%E4%B8%87%E6%AC%A1%22%5D%0A%20%20OFF%20--%3E%20HIT2%5B%22%E5%91%BD%E4%B8%AD%E5%8D%B3%E8%A7%A3%E5%AF%86%E5%85%A8%E9%83%A8%20WPA2%20%E6%B5%81%E9%87%8F%22%5D%0A%20%20SAE%5B%22SAE%EF%BC%9A%E6%AF%8F%E7%8C%9C%E4%B8%80%E6%AC%A1%E9%A1%BB%E4%B8%8E%20AP%20%E4%BA%A4%E4%BA%92%22%5D%20--%3E%20RATE%5B%22AP%20%E5%8F%AF%E9%99%90%E9%80%9F%E6%88%96%E9%94%81%E5%AE%9A%22%5D%0A%20%20RATE%20--%3E%20HIT3%5B%22%E7%A9%B7%E4%B8%BE%E8%A2%AB%E6%8A%AC%E6%88%90%E5%9C%A8%E7%BA%BF%E6%94%BB%E5%87%BB%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">直觉类比：WPA2-PSK 像把家门钥匙的型号印在门上，小偷可以抄回家慢慢配钥匙（离线猜）；SAE 规定配钥匙必须当面来，且每次只试一把——把穷举从「不限速」压到「受柜台限速」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写抓握手的操作。DNS 缓存投毒下一课：解析路径上的欺骗。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隧道之上，无线仍是广播。</li><li>WPA2-PSK 共享秘密；WPA3-SAE 改握手；企业用 802.1X。</li><li>链路保密不替代应用 TLS 与身份。</li><li>下一课 DNS 缓存投毒。</li><li>出处：IEEE 802.11i；WPA3；Fluhrer, Mantin and Shamir 对 WEP（历史）。</li></ul>',5))])}const c=n(p,[["render",d]]);export{u as __pageData,c as default};
